create policy "media readable for signing" on storage.objects for select to anon, authenticated using (bucket_id = 'media');
create policy "owner upload media" on storage.objects for insert to authenticated with check (bucket_id = 'media' and public.has_role(auth.uid(),'admin') and lower(storage.extension(name)) in ('jpg','jpeg','png','webp','heic'));
create policy "owner update media" on storage.objects for update to authenticated using (bucket_id = 'media' and public.has_role(auth.uid(),'admin'));
create policy "owner delete media" on storage.objects for delete to authenticated using (bucket_id = 'media' and public.has_role(auth.uid(),'admin'));